#include <memory>
#include <iostream>

class Resource { public: ~Resource() { std::cout << "Deleted!\n"; } };

void transfer_ownership() {
    std::auto_ptr<Resource> ptr1(new Resource);
    std::cout << "Ptr1 owning: " << (ptr1.get() != nullptr) << "\n";

    std::auto_ptr<Resource> ptr2 = ptr1; // Ownership transfer

    // ptr1 is now null after the 'copy' operation
    std::cout << "Ptr1 owning after copy: " << (ptr1.get() != nullptr) << "\n";
    std::cout << "Ptr2 owning: " << (ptr2.get() != nullptr) << "\n";
    // Resource deleted when ptr2 goes out of scope
}
